        Id unchangedEmailNotOptedOutId = fflib_IDGenerator.generate(Contact.SObjectType);

        Contact oldChangedEmail = new Contact(
            Id = changedEmailId,
            LastName = 'Changed Email',
            Email = 'old@example.com',
            HasOptedOutOfEmail = true
        );
        Contact oldUnchangedEmailOptedOut = new Contact(
            Id = unchangedEmailOptedOutId,
            LastName = 'Unchanged Email Opted Out',
            Email = 'same@example.com',
            HasOptedOutOfEmail = true
        );
        Contact oldUnchangedEmailNotOptedOut = new Contact(
            Id = unchangedEmailNotOptedOutId,
            LastName = 'Unchanged Email Not Opted Out',
            Email = 'also-same@example.com',
            HasOptedOutOfEmail = false
        );

        Contact newChangedEmail = oldChangedEmail.clone(true, false, false, false);
        newChangedEmail.Email = 'new@example.com';
        newChangedEmail.HasOptedOutOfEmail = true;

        Contact newUnchangedEmailOptedOut = oldUnchangedEmailOptedOut.clone(true, false, false, false);
        newUnchangedEmailOptedOut.HasOptedOutOfEmail = true;

        Contact newUnchangedEmailNotOptedOut = oldUnchangedEmailNotOptedOut.clone(true, false, false, false);
        newUnchangedEmailNotOptedOut.HasOptedOutOfEmail = false;

        Map<Id, Contact> oldRecords = new Map<Id, Contact>{
            oldChangedEmail.Id => oldChangedEmail,
            oldUnchangedEmailOptedOut.Id => oldUnchangedEmailOptedOut,
            oldUnchangedEmailNotOptedOut.Id => oldUnchangedEmailNotOptedOut
        };
        List<Contact> newRecords = new List<Contact>{
            newChangedEmail,
            newUnchangedEmailOptedOut,
            newUnchangedEmailNotOptedOut
        };

        fflib_SObjectDomain.Test.Database.onUpdate(newRecords, oldRecords);
        fflib_SObjectDomain.triggerHandler(Contacts.class);

        System.assertEquals(
