            newUnchangedEmailOptedOut.HasOptedOutOfEmail,
            'A Contact whose Email did not change should keep HasOptedOutOfEmail = true.'
        );
        System.assertEquals(
            false,
            newUnchangedEmailNotOptedOut.HasOptedOutOfEmail,
            'A Contact whose Email did not change should keep HasOptedOutOfEmail = false.'
        );
