        );

        List<Contact> records = new List<Contact>{
            yesterdayBirthdate,
            todayBirthdate,
            nullBirthdate,
            futureBirthdate
        };

        fflib_SObjectDomain.Test.Database.onInsert(records);
        fflib_SObjectDomain.triggerHandler(Contacts.class);

        assertNoErrors(yesterdayBirthdate, 'A Birthdate before today should be accepted on insert.');
        assertNoErrors(todayBirthdate, 'A Birthdate of today should be accepted on insert.');
        assertNoErrors(nullBirthdate, 'A blank Birthdate should be accepted on insert.');
        assertFutureBirthdateError(futureBirthdate);
