    @IsTest
    static void onUpdateRejectsOnlyFutureBirthdates() {
        Id yesterdayBirthdateId = fflib_IDGenerator.generate(Contact.SObjectType);
        Id todayBirthdateId = fflib_IDGenerator.generate(Contact.SObjectType);
        Id nullBirthdateId = fflib_IDGenerator.generate(Contact.SObjectType);
        Id futureBirthdateId = fflib_IDGenerator.generate(Contact.SObjectType);

        Contact oldYesterdayBirthdate = new Contact(
            Id = yesterdayBirthdateId,
            LastName = 'Yesterday Birthdate',
            Birthdate = Date.today().addDays(-30)
        );
        Contact oldTodayBirthdate = new Contact(
            Id = todayBirthdateId,
            LastName = 'Today Birthdate',
            Birthdate = Date.today().addDays(-30)
        );
        Contact oldNullBirthdate = new Contact(
            Id = nullBirthdateId,
            LastName = 'Null Birthdate',
            Birthdate = Date.today().addDays(-30)
        );
        Contact oldFutureBirthdate = new Contact(
            Id = futureBirthdateId,
            LastName = 'Future Birthdate',
            Birthdate = Date.today()
        );

        Contact newYesterdayBirthdate = oldYesterdayBirthdate.clone(true, false, false, false);
        newYesterdayBirthdate.Birthdate = Date.today().addDays(-1);

        Contact newTodayBirthdate = oldTodayBirthdate.clone(true, false, false, false);
        newTodayBirthdate.Birthdate = Date.today();

        Contact newNullBirthdate = oldNullBirthdate.clone(true, false, false, false);
        newNullBirthdate.Birthdate = null;

        Contact newFutureBirthdate = oldFutureBirthdate.clone(true, false, false, false);
        newFutureBirthdate.Birthdate = Date.today().addDays(1);

        Map<Id, Contact> oldRecords = new Map<Id, Contact>{
            oldYesterdayBirthdate.Id => oldYesterdayBirthdate,
            oldTodayBirthdate.Id => oldTodayBirthdate,
            oldNullBirthdate.Id => oldNullBirthdate,
            oldFutureBirthdate.Id => oldFutureBirthdate
        };
        List<Contact> newRecords = new List<Contact>{
            newYesterdayBirthdate,
            newTodayBirthdate,
            newNullBirthdate,
            newFutureBirthdate
        };

        fflib_SObjectDomain.Test.Database.onUpdate(newRecords, oldRecords);
        fflib_SObjectDomain.triggerHandler(Contacts.class);

        assertNoErrors(newYesterdayBirthdate, 'A Birthdate before today should be accepted on update.');
        assertNoErrors(newTodayBirthdate, 'A Birthdate of today should be accepted on update.');
        assertNoErrors(newNullBirthdate, 'A blank Birthdate should be accepted on update.');
        assertFutureBirthdateError(newFutureBirthdate);
    }

    private static void assertFutureBirthdateError(Contact record) {
        List<Database.Error> errors = record.getErrors();

        System.assertEquals(1, errors.size(), 'A future Birthdate should receive exactly one validation error.');
        System.assertEquals(
            Contacts.FUTURE_BIRTHDATE,
            errors[0].getMessage(),
            'The future Birthdate validation error message should match Contacts.FUTURE_BIRTHDATE.'
        );
        System.assertEquals(
            new List<String>{ 'Birthdate' },
            errors[0].getFields(),
            'The future Birthdate validation error should be on the Birthdate field.'
        );
    }

    private static void assertNoErrors(SObject record, String message) {
        System.assertEquals(0, record.getErrors().size(), message);
    }
