        validateAmountNotNegative();
    }

    public override void onValidate(Map<Id, SObject> existingRecords) {
        validateAmountNotNegative();
        validateWonOpportunityAmountNotChanged(existingRecords);
    }

    private void validateAmountNotNegative() {
        for (Opportunity opportunityRecord : (List<Opportunity>) Records) {
            if (opportunityRecord.Amount != null && opportunityRecord.Amount < 0) {
                error('Amount cannot be negative.', opportunityRecord, Opportunity.Amount);
            }
        }
    }

    private void validateWonOpportunityAmountNotChanged(Map<Id, SObject> existingRecords) {
        for (Opportunity opportunityRecord : (List<Opportunity>) Records) {
            Opportunity oldOpportunityRecord = (Opportunity) existingRecords.get(opportunityRecord.Id);

            if (
                oldOpportunityRecord != null &&
                oldOpportunityRecord.StageName == 'Closed Won' &&
                opportunityRecord.Amount != oldOpportunityRecord.Amount
            ) {
                error(
                    'Amount cannot change on a won opportunity.',
                    opportunityRecord,
                    Opportunity.Amount
                );
            }
        }
    }
}
