public with sharing class CaseSurveyJob implements Queueable {
    private final Id caseId;
    private final List<Id> remainingCaseIds;

    public CaseSurveyJob(Id caseId) {
        this.caseId = caseId;
        this.remainingCaseIds = new List<Id>();
    }

    private CaseSurveyJob(Id caseId, List<Id> remainingCaseIds) {
        this.caseId = caseId;
        this.remainingCaseIds = remainingCaseIds == null ? new List<Id>() : remainingCaseIds;
    }

    public static void enqueue(List<Id> caseIds) {
        if (caseIds == null || caseIds.isEmpty()) {
            return;
        }

        List<Id> idsToProcess = new List<Id>(caseIds);
        Id firstCaseId = idsToProcess.remove(0);

        System.enqueueJob(new CaseSurveyJob(firstCaseId, idsToProcess));
    }

    public void execute(QueueableContext context) {
        if (caseId != null) {
            createSurveyTask(caseId);
        }

        if (remainingCaseIds != null && !remainingCaseIds.isEmpty()) {
            List<Id> nextRemainingCaseIds = new List<Id>(remainingCaseIds);
            Id nextCaseId = nextRemainingCaseIds.remove(0);

            System.enqueueJob(new CaseSurveyJob(nextCaseId, nextRemainingCaseIds));
        }
    }

    private static void createSurveyTask(Id caseIdToProcess) {
        List<Case> cases = [
            SELECT Id, CaseNumber, ContactId
            FROM Case
            WHERE Id = :caseIdToProcess
            AND ContactId != null
            LIMIT 1
        ];

        if (cases.isEmpty()) {
            return;
        }

        Case surveyCase = cases[0];

        insert new Task(
            WhatId = surveyCase.Id,
            WhoId = surveyCase.ContactId,
            Subject = 'CSAT survey: ' + surveyCase.CaseNumber,
            ActivityDate = Date.today().addDays(2),
            Status = 'Not Started'
        );
    }
}
