public with sharing class HouseholdService {
    public static Id createHousehold(List<Contact> members) {
        if (members == null || members.isEmpty()) {
            throw new IllegalArgumentException('members must not be null or empty');
        }

        Map<String, Schema.RecordTypeInfo> accountRecordTypesByDeveloperName =
            Schema.SObjectType.Account.getRecordTypeInfosByDeveloperName();

        if (!accountRecordTypesByDeveloperName.containsKey('HH_Account')) {
            throw new IllegalArgumentException('Household Account record type HH_Account was not found');
        }

        Id householdRecordTypeId = accountRecordTypesByDeveloperName.get('HH_Account').getRecordTypeId();

        /*
         * NPSP creates and names a household automatically when a Contact is inserted
         * without an AccountId. Insert the primary contact first so NPSP creates exactly
         * one household, then use that Account for all remaining family members.
         */
        Contact primaryContact = members[0].clone(false, true, false, false);
        primaryContact.AccountId = null;
        insert primaryContact;

        Id householdId = [
            SELECT AccountId
            FROM Contact
            WHERE Id = :primaryContact.Id
            LIMIT 1
        ].AccountId;

        if (householdId == null) {
            throw new DmlException('NPSP did not create a household account for the primary contact');
        }

        Account household = [
            SELECT Id, RecordTypeId, npe01__One2OneContact__c
            FROM Account
            WHERE Id = :householdId
            LIMIT 1
        ];

        /*
         * Ensure the created account is the NPSP Household Account record type. This is
         * normally the org default under the Household Account model, but setting the
         * record type explicitly avoids relying on the running user's default.
         */
        Boolean householdNeedsUpdate = false;
        if (household.RecordTypeId != householdRecordTypeId) {
            household.RecordTypeId = householdRecordTypeId;
            householdNeedsUpdate = true;
        }
        if (household.npe01__One2OneContact__c != primaryContact.Id) {
            household.npe01__One2OneContact__c = primaryContact.Id;
            householdNeedsUpdate = true;
        }
        if (householdNeedsUpdate) {
            update household;
        }

        if (members.size() > 1) {
            List<Contact> additionalContacts = new List<Contact>();

            for (Integer i = 1; i < members.size(); i++) {
                if (members[i] == null) {
                    throw new IllegalArgumentException('members must not contain null contacts');
                }

                Contact additionalContact = members[i].clone(false, true, false, false);
                additionalContact.AccountId = householdId;
                additionalContacts.add(additionalContact);
            }

            insert additionalContacts;
        }

        return householdId;
    }
}
